-- leaseEvent
DO $authz$
DECLARE p record;
BEGIN
  FOR p IN SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'leaseEvent' LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, 'leaseEvent');
  END LOOP;
END
$authz$;
ALTER TABLE public."leaseEvent" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "SELECT" ON "public"."leaseEvent" FOR SELECT USING ("companyId" = ANY ((SELECT get_companies_with_employee_permission('purchasing_view'))::text[]));

